'use strict';
function accountDestination(){return principal?.kind==='employee'?'مسح البطاقة':principal?.kind==='admin'?'لوحة الإدارة':principal?.kind==='customer'?'بطاقتي':'لوحة التحكم';}
function navigationKey(){return 'rijaa:navigation:'+principal.kind+':'+(principal.account||principal.employee||principal.email||principal.shop||'');}
function accountViews(){return principal.kind==='employee'?['scan','activity']:principal.kind==='admin'?navAdmin.map(n=>n[0]):navOwner.map(n=>n[0]);}
function restoreAccountView(){publicPage='';view=principal.kind==='employee'?'scan':principal.kind==='admin'?'accounts':'overview';try{const saved=JSON.parse(localStorage.getItem(navigationKey())||'null');if(saved&&accountViews().includes(saved.view)){view=saved.view;if(db.shops.some(s=>s.id===saved.shop&&!s.archivedAt))db.shop=saved.shop;}}catch{}}
function openAccount(){role={owner:'owner',employee:'staff',admin:'admin',customer:'client'}[principal.kind];restoreAccountView();history.replaceState(null,'',role==='admin'?'/admin':'/login');render();}
const accountNav=publicNav;
publicNav=function(){const html=accountNav().replace(/<button[^>]*data-action="demo-admin"[^>]*>.*?<\/button>/g,'');if(principal)return html.replace('data-action="login">تسجيل الدخول','data-action="account-dashboard">'+accountDestination()).replace('<div class="actions">','<div class="actions"><button class="btn secondary" data-action="access-login">تسجيل الدخول</button><button class="btn secondary" data-action="access-login" data-register="1">إنشاء حساب</button>');return !principal&&!window.RIJAA_DEMO?html.replace('<div class="actions">','<div class="actions"><button class="btn secondary" data-action="visitor-demo">تجربة الأدمن</button>'):html;};
window.addEventListener('click',e=>{if(!e.target.closest('[data-action=visitor-demo]'))return;e.preventDefault();e.stopImmediatePropagation();if(!principal)location.assign('/demo.html');},true);
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(serverMode&&principal&&['account-dashboard','login','home','access-login'].includes(b.dataset.action)){e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='access-login'){history.replaceState(null,'','/login?switch=1');publicPage='login';loginType='owner';loginStep='phone';emailStep='form';emailForgot=false;emailAddress='';newBusiness=b.dataset.register==='1';render();}else if(b.dataset.action==='home'){history.replaceState(null,'','/?home=1');publicPage='home';render();}else openAccount();}},true);
const experienceRender=render;
render=function(){if(serverMode&&principal&&publicPage==='login'&&new URLSearchParams(location.search).get('switch')!=='1'){role={owner:'owner',employee:'staff',admin:'admin',customer:'client'}[principal.kind];restoreAccountView();}experienceRender();const dashboardBrand=document.querySelector('.sidebar .brand');if(dashboardBrand)dashboardBrand.innerHTML='<span class="ocean-brand-lockup"><img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء"><img class="rijaa-brand-logo brand-white-word" src="/brand-logo.png" alt="" aria-hidden="true"></span>';if(serverMode&&principal&&!publicPage){let bar=document.querySelector('.topbar');if(!bar){bar=document.createElement('header');bar.className='topbar';document.querySelector('#app')?.prepend(bar);const exit=document.createElement('button');exit.className='btn quiet small';exit.textContent='تسجيل الخروج';exit.dataset.action='server-logout';bar.append(exit);}if(role!=='client'&&!bar.querySelector('[data-action=home]')){const home=document.createElement('button');home.className='btn quiet small';home.textContent='الرئيسية';home.dataset.action='home';bar.prepend(home);}const expected={owner:'owner',employee:'staff',admin:'admin',customer:'client'}[principal.kind];if(role===expected&&accountViews().includes(view)){try{localStorage.setItem(navigationKey(),JSON.stringify({view,shop:db.shop}));}catch{}}const brand=document.querySelector('.sidebar .brand');if(brand){brand.dataset.action='account-dashboard';brand.removeAttribute('data-role');}}
const auth=document.querySelector('.auth-layout');if(auth){document.body.classList.add('neon-auth');if(!document.querySelector('.public-nav'))auth.insertAdjacentHTML('beforebegin',publicNav());document.querySelectorAll('.public-brand').forEach(b=>b.innerHTML='<span class="ocean-brand-lockup"><img class="rijaa-brand-logo" src="/brand-logo.png" alt="رجعة — نظام الولاء"><img class="rijaa-brand-logo brand-white-word" src="/brand-logo.png" alt="" aria-hidden="true"></span>');auth.querySelector('.notice')?.remove();auth.querySelector('.brand')?.remove();auth.querySelector('section:first-child').insertAdjacentHTML('beforeend','<div class="auth-feature-list"><span>✦ هوية نشاطك، بكل تفاصيلها</span><span>▣ بطاقاتك وفريقك في مكان واحد</span><span>↗ كل زيارة تقرّب عميلك للمكافأة</span></div>');auth.querySelectorAll('input[type=password]').forEach((input,i)=>{input.id=input.id||'auth-password-'+i;input.closest('label').insertAdjacentHTML('beforeend',`<button type="button" class="password-toggle" data-action="toggle-password-visibility" data-target="${input.id}" aria-controls="${input.id}" aria-pressed="false">إظهار كلمة المرور</button>`);});auth.querySelectorAll('.btn.primary').forEach(b=>{if(b.querySelector('.glow-orbit'))return;const label=b.textContent;b.classList.add('glow-button');b.innerHTML=`<span class="glow-orbit" aria-hidden="true"><span>↗</span></span><span class="glow-label">${esc(label)}</span>`;});}else document.body.classList.remove('neon-auth');};
document.addEventListener('pointermove',e=>{if(!document.body.classList.contains('neon-auth'))return;document.body.style.setProperty('--neon-x',`${Math.round(e.clientX/innerWidth*100)}%`);document.body.style.setProperty('--neon-y',`${Math.round(e.clientY/innerHeight*100)}%`);},{passive:true});
render();

window.addEventListener('click',e=>{const b=e.target.closest('[data-action=toggle-password-visibility]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const input=document.getElementById(b.dataset.target);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'إخفاء كلمة المرور':'إظهار كلمة المرور';b.setAttribute('aria-pressed',String(show));},true);

let workspacePointerFrame=0,workspacePointerX=65,workspacePointerY=25;
document.addEventListener('pointermove',e=>{if(!document.querySelector('.app-shell')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;workspacePointerX=Math.round(e.clientX/innerWidth*100);workspacePointerY=Math.round(e.clientY/innerHeight*100);if(workspacePointerFrame)return;workspacePointerFrame=requestAnimationFrame(()=>{document.body.style.setProperty('--workspace-x',workspacePointerX+'%');document.body.style.setProperty('--workspace-y',workspacePointerY+'%');workspacePointerFrame=0;});},{passive:true});
